
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_tca_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_tca", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.669158051797877e-02, -6.615429796474101e-02, -6.535800648761191e-02, -6.416358480968151e-02, -6.234330517387241e-02, -5.951477447108152e-02, -5.503346410914550e-02, -4.789423442745478e-02, -3.708289524272176e-02, -2.394563573637020e-02, -1.727939476053753e-02, -3.928408848015355e-02, -4.356566930820968e-02, -3.191763350309000e-02, -1.613688542379319e-02, -4.207299469823175e-03, -4.017769853130104e-04, -1.085593505629469e-05, -5.995907401503814e-08, -4.040910088670973e-11]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


